 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    original = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != background}
    connectors = []
    # Join every pair of 1s aligned on a 45-degree diagonal.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2-r1, c2-c1
            if dr and abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                line = []
                r, c = r1, c1
                while True:
                    line.append((r, c))
                    if (r, c) == (r2, c2):
                        break
                    r += sr
                    c += sc
                connectors.append((set(line), sc == sr))
                for r, c in line:
                    if grid[r][c] == background:
                        out[r][c] = 1
    # A 6 on a connector draws the other diagonal through itself, to both borders.
    for r0, c0 in sixes:
        connector = next((slope_down for cells, slope_down in connectors if (r0, c0) in cells), None)
        if connector is None:
            continue
        # Connector slope +1 => draw slope -1; connector slope -1 => draw slope +1.
        sr, sc = 1, -1 if connector else 1
        r, c = r0, c0
        while 0 <= r-sr < h and 0 <= c-sc < w:
            r -= sr
            c -= sc
        while 0 <= r < h and 0 <= c < w:
            if (r, c) not in original:
                out[r][c] = 6
            r += sr
            c += sc
    return out
